+}): { date: string; mood: number; energy: number; sleep_hours: number; notes: string | null } {
+  return {
+    date: form.date,
+    mood: form.mood,
+    energy: form.energy,
+    sleep_hours: form.sleepHours,
+    notes: form.notes || null,
+  };
+}

